import numpy as np
rule=json.load(open('table.json'))
syms='ABCDE'; m={c:i for i,c in enumerate(syms)}
pts=[(m[k[0]],m[k[1]],m[k[2]],m[v]) for k,v in rule.items()]
for deg in range(0,5):
    mons=[]
    for a in range(5):
      for b in range(5):
        for c in range(5):
          if a+b+c<=deg:
            mons.append((a,b,c))
    A=np.zeros((125,len(mons)),dtype=int)
    y=np.array([o for *_,o in pts],dtype=int)
    for i,(x1,x2,x3,o) in enumerate(pts):
      for j,(a,b,c) in enumerate(mons):
        A[i,j]=(pow(x1,a,5)*pow(x2,b,5)*pow(x3,c,5))%5
    # solve mod5 by row reduction, see if exact solution exists
    M=np.concatenate([A,y[:,None]],axis=1)%5
    r=0; piv=[]
    rows,cols=A.shape
    for c in range(cols):
      pivrow=None
      for i in range(r,rows):
        if M[i,c]%5!=0:
          pivrow=i; break
      if pivrow is None: continue
      M[[r,pivrow]]=M[[pivrow,r]]
      inv=pow(int(M[r,c]),-1,5)
      M[r]=(M[r]*inv)%5
      for i in range(rows):
        if i!=r and M[i,c]%5!=0:
          M[i]=(M[i]-M[i,c]*M[r])%5
      piv.append(c); r+=1
      if r==rows: break
    inconsistent=any(M[i,:cols].sum()==0 and M[i,cols]!=0 for i in range(rows))
    print('deg',deg,'mons',len(mons),'rank',r,'solvable',not inconsistent)
