def berlekamp_massey(s, mod=5):
    C=[1]; B=[1]
    L=0; m=1; b=1
    for n in range(len(s)):
        d=s[n]
        for i in range(1,L+1):
            d=(d + C[i]*s[n-i])%mod
        if d==0:
            m+=1
            continue
        coef=d*pow(b,-1,mod)%mod
        T=C[:]
        if len(C)<len(B)+m:
            C += [0]*(len(B)+m-len(C))
        for i in range(len(B)):
            C[i+m]=(C[i+m]-coef*B[i])%mod
        if 2*L<=n:
            L=n+1-L
            B=T
            b=d
            m=1
        else:
            m+=1
    # recurrence: s[n] = -sum_{i=1..L} C[i] s[n-i]
    rec=[(-C[i])%mod for i in range(1,L+1)]
    return rec

def lin_predict(rec, init, n, mod=5):
    # init length k = len(rec), returns a_n where a_i=init[i]
    k=len(rec)
    if n < len(init): return init[n]%mod
    def combine(a,b):
        # poly mod characteristic x^k - rec[0]x^{k-1}-...-rec[k-1]
        res=[0]*(2*k)
        for i,x in enumerate(a):
            if x:
                for j,y in enumerate(b):
                    if y:
                        res[i+j]=(res[i+j]+x*y)%mod
        for i in range(2*k-2, k-1, -1):
            v=res[i]
            if v:
                for j in range(k):
                    res[i-1-j]=(res[i-1-j]+v*rec[j])%mod
        return res[:k]
    # coefficient vector for a_n in terms of init[0..k-1]
    pol=[1]+[0]*(k-1)  # x^0
    e=[0,1]+[0]*(k-2) if k>1 else [rec[0]]
    m=n
    while m:
        if m&1:
            pol=combine(pol,e)
        e=combine(e,e)
        m//=2
    ans=0
    for i,c in enumerate(pol):
        ans=(ans + c*init[i])%mod
    return ans

for q in qs:
    seq=seqs[q]
    best=None
    for train in [200,400,800,1200,2000,3000,4000]:
